#!/usr/bin/env bash
set -Eeuo pipefail
PROJECT="/scratch/lj2634/Isaac-Go2-Low-Level-RL"; EXP="$PROJECT/experiments/r8_56_hold_bias_video"; PY="/scratch/lj2634/envs/isaaclab232_v2/bin/python"
echo '===== R8.56 PREFLIGHT (NO GPU) ====='; bash -n "$EXP/run_r856_scan.sbatch" "$EXP/check_r856_latest.sh" "$EXP/build_r856_video_bundle.sh" "$EXP/check_r856_video_bundle.sh" "$EXP/render_r856_local.sh" "$EXP/check_r856_local_videos.sh"; "$PY" -m py_compile "$EXP/patch_r856_source.py"; echo SCRIPT_SYNTAX=OK
R855="$(tr -d '\r\n' < /scratch/lj2634/runs/go2_soccer_r8_55_touchdown_hold/latest_r855.txt)"; R851="$(tr -d '\r\n' < /scratch/lj2634/runs/go2_soccer_r8_51_kick64_true_contact/latest_r851.txt)"; R850="$(tr -d '\r\n' < "$PROJECT/experiments/r8_50_real_contact_truth/latest_r850.txt")"; SOURCE="$R855/train_r855_touchdown_hold.py"
for f in "$SOURCE" "$R855/output/recovery64_final.pt" "$R851/output/kick64_final.pt" "$R851/output/r851_summary.json" "$R850/body_names.json"; do [[ -s "$f" ]]||{ echo "PREFLIGHT_FATAL missing: $f" >&2; exit 32; }; stat --printf='READY %n %s bytes\n' "$f"; done
TMP="$(mktemp -d /scratch/lj2634/r856_preflight_XXXXXX)"; trap 'rm -rf -- "$TMP"' EXIT; "$PY" "$EXP/patch_r856_source.py" --source "$SOURCE" --output "$TMP/train_r856.py"; "$PY" -m py_compile "$TMP/train_r856.py"; grep -q 'def _r856_fl_joint_ids' "$TMP/train_r856.py"; grep -q 'def run_r856_video' "$TMP/train_r856.py"; grep -q 'R856_HOLD_SCAN_ONLY' "$TMP/train_r856.py"; echo "SOURCE_SHA256=$(sha256sum "$SOURCE"|awk '{print $1}')"; echo PATCH_INJECTION=OK; echo VIDEO_BRANCH=OK; echo R856_PREFLIGHT_OK
